interface.definition:
a!localVariables(
  local!showRotational: or(
    a!isNullOrEmpty(ri!typeFilter),
    ri!typeFilter = "Rotational"
  ),
  local!showCore: or(
    a!isNullOrEmpty(ri!typeFilter),
    ri!typeFilter = "Core"
  ),
  local!filteredTotalInternationalConfirmed: if(
    a!isNullOrEmpty(ri!typeFilter),
    count(ri!fyInternationalConfirmed),
    if(
      ri!typeFilter = "Rotational",
      count(ri!fyInternationalConfirmed),
      0
    )
  ),
  local!filteredTotalInternationalInProcess: if(
    a!isNullOrEmpty(ri!typeFilter),
    count(ri!fyInternationalInProcess),
    if(
      ri!typeFilter = "Rotational",
      count(ri!fyInternationalInProcess),
      0
    )
  ),
  local!externalOtherRotationalsConfirmed: count(
    wherecontains(
      #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6648284",
      tointeger(index(ri!externalNominationsConfirmed,"subPositionTypeId",{}))
    )
  ),
  local!externalOtherRotationalsInProcess: count(
    wherecontains(
      #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6648284",
      tointeger(index(ri!externalNominationsInProcess,"subPositionTypeId",{}))
    )
  ),
  local!externalTransitionalCoresConfirmed: count(
    wherecontains(
      #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4147895",
      tointeger(index(ri!externalNominationsConfirmed,"subPositionTypeId",{}))
    )
  ),
  local!externalTransitionalCoresInProcess: count(
    wherecontains(
      #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4147895",
      tointeger(index(ri!externalNominationsInProcess,"subPositionTypeId",{}))
    )
  ),
  local!externalOtherCoresConfirmed: count(
    wherecontains(
      #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6648367",
      tointeger(index(ri!externalNominationsConfirmed,"subPositionTypeId",{}))
    )
  ),
  local!externalOtherCoresInProcess: count(
    wherecontains(
      #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6648367",
      tointeger(index(ri!externalNominationsInProcess,"subPositionTypeId",{}))
    )
  ),
  local!filteredTotalExternalConfirmed: if(
    a!isNullOrEmpty(ri!typeFilter),
    count(ri!externalNominationsConfirmed),
    if(
      ri!typeFilter = "Rotational",
      local!externalOtherRotationalsConfirmed,
      sum(
        local!externalTransitionalCoresConfirmed,
        local!externalOtherCoresConfirmed
      )
    )
  ),
  local!filteredTotalExternalInProcess: if(
    a!isNullOrEmpty(ri!typeFilter),
    count(ri!externalNominationsInProcess),
    if(
      ri!typeFilter = "Rotational",
      local!externalOtherRotationalsInProcess,
      sum(
        local!externalTransitionalCoresInProcess,
        local!externalOtherCoresInProcess
      )
    )
  ),
  local!internalOtherRotationalsConfirmed: count(
    wherecontains(
      #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6648284",
      tointeger(index(ri!internalNominationsConfirmed,"subPositionTypeId",{}))
    )
  ),
  local!internalOtherRotationalsInProcess: count(
    wherecontains(
      #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6648284",
      tointeger(index(ri!internalNominationsInProcess,"subPositionTypeId",{}))
    )
  ),
  local!internalTransitionalCoresConfirmed: count(
    wherecontains(
      #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4147895",
      tointeger(index(ri!internalNominationsConfirmed,"subPositionTypeId",{}))
    )
  ),
  local!internalTransitionalCoresInProcess: count(
    wherecontains(
      #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4147895",
      tointeger(index(ri!internalNominationsInProcess,"subPositionTypeId",{}))
    )
  ),
  local!internalOtherCoresConfirmed: count(
    wherecontains(
      #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6648367",
      tointeger(index(ri!internalNominationsConfirmed,"subPositionTypeId",{}))
    )
  ),
  local!internalOtherCoresInProcess: count(
    wherecontains(
      #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6648367",
      tointeger(index(ri!internalNominationsInProcess,"subPositionTypeId",{}))
    )
  ),
  local!filteredTotalInternalConfirmed: if(
    a!isNullOrEmpty(ri!typeFilter),
    count(ri!internalNominationsConfirmed),
    if(
      ri!typeFilter = "Rotational",
      local!internalOtherRotationalsConfirmed,
      sum(
        local!internalTransitionalCoresConfirmed,
        local!internalOtherCoresConfirmed
      )
    )
  ),
  local!filteredTotalInternalInProcess: if(
    a!isNullOrEmpty(ri!typeFilter),
    count(ri!internalNominationsInProcess),
    if(
      ri!typeFilter = "Rotational",
      local!internalOtherRotationalsInProcess,
      sum(
        local!internalTransitionalCoresInProcess,
        local!internalOtherCoresInProcess
      )
    )
  ),
  #"SYSTEM_SYSRULES_cardLayout"(
    contents: #"SYSTEM_SYSRULES_columnsLayout"(
      columns: {
        /* Other */
